H,W = len(inp), len(inp[0])
# blob = connected non-bg component containing the 1
from collections import deque
start = [(r,c) for r in range(H) for c in range(W) if inp[r][c]==1][0]
seen={start}; q=deque([start])
while q:
    r,c=q.popleft()
    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
        rr,cc=r+dr,c+dc
        if 0<=rr<H and 0<=cc<W and (rr,cc) not in seen and inp[rr][cc]!=bg:
            seen.add((rr,cc)); q.append((rr,cc))
rs=[r for r,c in seen]; cs=[c for r,c in seen]
r0,r1,c0,c1 = min(rs),max(rs),min(cs),max(cs)
motif = [[inp[r][c] for c in range(c0,c1+1)] for r in range(r0,r1+1)]
print("motif", motif, "center", motif[len(motif)//2][len(motif[0])//2])
mh,mw = len(motif), len(motif[0])
markers = [(r,c) for r in range(H) for c in range(W) if inp[r][c]!=bg and (r,c) not in seen]
print(sorted(markers))
out = [row[:] for row in inp]
for (r,c) in markers:
    for i in range(mh):
        for j in range(mw):
            rr,cc = r+i-mh//2, c+j-mw//2
            if 0<=rr<H and 0<=cc<W:
                out[rr][cc] = motif[i][j]
for row in out: print(row)
